-- HADS Phase 1 baseline DDL | PostgreSQL 17+ | 2026-10-07
-- Review before production. Application must enforce state machines, authorization and evidence immutability.
BEGIN;
CREATE TABLE sys_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), display_name text NOT NULL, email text UNIQUE NOT NULL, role text NOT NULL CHECK(role IN ('TECHNICIAN','REVIEWER','ADMIN')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), display_name text NOT NULL, phone text, email text, notes text, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), row_version bigint NOT NULL DEFAULT 0);
CREATE TABLE service_addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid REFERENCES customers(id) ON DELETE RESTRICT, line1 text NOT NULL, line2 text, city text NOT NULL, province text NOT NULL DEFAULT 'NS', postal_code text, country text NOT NULL DEFAULT 'CA', row_version bigint NOT NULL DEFAULT 0, archived_at timestamptz);
CREATE TABLE appliances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), appliance_type text NOT NULL, brand text, model_no text, serial_no text, serial_verified boolean NOT NULL DEFAULT false, identity_notes text, created_at timestamptz NOT NULL DEFAULT now(), archived_at timestamptz, row_version bigint NOT NULL DEFAULT 0);
CREATE INDEX ix_appliance_identity ON appliances(brand,model_no,serial_no);
CREATE TABLE appliance_location_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), appliance_id uuid NOT NULL REFERENCES appliances(id) ON DELETE RESTRICT, address_id uuid REFERENCES service_addresses(id) ON DELETE RESTRICT, customer_id uuid REFERENCES customers(id) ON DELETE RESTRICT, valid_from timestamptz NOT NULL, valid_to timestamptz, note text, CHECK(valid_to IS NULL OR valid_to>valid_from));
CREATE INDEX ix_appliance_location ON appliance_location_history(appliance_id,valid_from DESC);
CREATE TABLE diagnostic_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), appliance_id uuid NOT NULL REFERENCES appliances(id) ON DELETE RESTRICT, customer_id uuid REFERENCES customers(id) ON DELETE RESTRICT, service_address_id uuid REFERENCES service_addresses(id) ON DELETE RESTRICT, service_address_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, reported_symptoms text NOT NULL, error_codes text, workflow_status text NOT NULL DEFAULT 'OPEN' CHECK(workflow_status IN ('OPEN','DIAGNOSING','PENDING_AUTHORIZATION','PENDING_PARTS','IN_REPAIR','VERIFYING','ON_HOLD','CLOSED','CANCELLED')), disposition text CHECK(disposition IN ('FIXED_VERIFIED','UNRESOLVED','CUSTOMER_DECLINED','BER','UNSAFE','NO_FAULT_FOUND','REFERRED','CANCELLED')), hold_reason text, related_case_id uuid REFERENCES diagnostic_cases(id) ON DELETE RESTRICT, opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz, created_by uuid REFERENCES sys_users(id) ON DELETE RESTRICT, row_version bigint NOT NULL DEFAULT 0, CHECK(workflow_status <> 'CLOSED' OR disposition IS NOT NULL));
CREATE INDEX ix_case_appliance ON diagnostic_cases(appliance_id,opened_at DESC);
CREATE INDEX ix_case_status ON diagnostic_cases(workflow_status,opened_at DESC);
CREATE TABLE case_state_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES diagnostic_cases(id) ON DELETE RESTRICT, from_state text, to_state text NOT NULL, reason text, actor_user_id uuid REFERENCES sys_users(id) ON DELETE RESTRICT, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE service_visits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES diagnostic_cases(id) ON DELETE RESTRICT, technician_id uuid REFERENCES sys_users(id) ON DELETE RESTRICT, visit_status text NOT NULL DEFAULT 'PLANNED' CHECK(visit_status IN ('PLANNED','IN_PROGRESS','PAUSED','COMPLETED','CANCELLED')), started_at timestamptz, ended_at timestamptz, pause_reason text, notes text, row_version bigint NOT NULL DEFAULT 0, CHECK(ended_at IS NULL OR started_at IS NULL OR ended_at>=started_at));
CREATE INDEX ix_visits_case ON service_visits(case_id);
CREATE TABLE safety_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), visit_id uuid NOT NULL REFERENCES service_visits(id) ON DELETE RESTRICT, assessment_mode text NOT NULL CHECK(assessment_mode IN ('NOT_ASSESSED','CLEARED_STATIC','CLEARED_LIVE','STOP_WORK')), assessment_notes text, assessed_by uuid REFERENCES sys_users(id) ON DELETE RESTRICT, assessed_at timestamptz NOT NULL DEFAULT now(), valid_until timestamptz, supersedes_id uuid REFERENCES safety_assessments(id) ON DELETE RESTRICT);
CREATE TABLE safety_hazards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid NOT NULL REFERENCES safety_assessments(id) ON DELETE RESTRICT, hazard_code text NOT NULL, risk_level text CHECK(risk_level IN ('LOW','MEDIUM','HIGH','CRITICAL')), control_measure text, controlled boolean NOT NULL DEFAULT false);
CREATE TABLE diagnostic_hypotheses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES diagnostic_cases(id) ON DELETE RESTRICT, description text NOT NULL, priority smallint CHECK(priority BETWEEN 1 AND 5), hypothesis_status text NOT NULL DEFAULT 'PROPOSED' CHECK(hypothesis_status IN ('PROPOSED','TESTING','SUPPORTED','REFUTED','INCONCLUSIVE')), created_by uuid REFERENCES sys_users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ix_hyp_case ON diagnostic_hypotheses(case_id);
CREATE TABLE diagnostic_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hypothesis_id uuid NOT NULL REFERENCES diagnostic_hypotheses(id) ON DELETE RESTRICT, visit_id uuid REFERENCES service_visits(id) ON DELETE RESTRICT, step_order integer NOT NULL DEFAULT 1 CHECK(step_order>0), test_description text NOT NULL, test_point text, expected_result text, actual_observation text, interpretation text, next_step text, required_safety_mode text NOT NULL DEFAULT 'STATIC' CHECK(required_safety_mode IN ('STATIC','LIVE','NON_ELECTRICAL')), step_status text NOT NULL DEFAULT 'PLANNED' CHECK(step_status IN ('PLANNED','IN_PROGRESS','PASS','FAIL','INCONCLUSIVE','ABORTED')), performed_at timestamptz);
CREATE INDEX ix_steps_hyp ON diagnostic_steps(hypothesis_id,step_order);
CREATE TABLE tool_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tool_name text NOT NULL, make text, model text, serial_no text, calibration_due date, inspection_notes text, active boolean NOT NULL DEFAULT true);
CREATE TABLE measurement_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), step_id uuid NOT NULL REFERENCES diagnostic_steps(id) ON DELETE RESTRICT, tool_id uuid REFERENCES tool_assets(id) ON DELETE RESTRICT, reading_kind text NOT NULL CHECK(reading_kind IN ('NUMERIC','OL','UNSTABLE','NOT_MEASURED','ABORTED')), actual_value numeric(18,6), unit text, expected_value text, measurement_condition text, notes text, measured_at timestamptz NOT NULL DEFAULT now(), measured_by uuid REFERENCES sys_users(id) ON DELETE RESTRICT, CHECK((reading_kind='NUMERIC' AND actual_value IS NOT NULL) OR (reading_kind<>'NUMERIC' AND actual_value IS NULL)));
CREATE INDEX ix_measurement_step ON measurement_records(step_id,measured_at);
CREATE TABLE evidence_amendments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), target_table text NOT NULL CHECK(target_table IN ('measurement_records','diagnostic_steps','root_cause_findings','repair_actions','repair_verifications')), target_id uuid NOT NULL, replacement_payload jsonb NOT NULL, reason text NOT NULL, amended_by uuid REFERENCES sys_users(id) ON DELETE RESTRICT, amended_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE diagnostic_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES diagnostic_cases(id) ON DELETE RESTRICT, step_id uuid REFERENCES diagnostic_steps(id) ON DELETE RESTRICT, media_kind text NOT NULL CHECK(media_kind IN ('PHOTO','VIDEO','AUDIO','DOCUMENT','SIGNATURE')), object_key text UNIQUE NOT NULL, mime_type text NOT NULL, byte_size bigint NOT NULL CHECK(byte_size>=0), sha256_hex char(64) NOT NULL CHECK(sha256_hex ~ '^[0-9a-f]{64}$'), upload_status text NOT NULL DEFAULT 'PENDING' CHECK(upload_status IN ('PENDING','UPLOADING','UPLOADED','VERIFIED','FAILED')), captured_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ix_media_case ON diagnostic_media(case_id);
CREATE TABLE root_cause_findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES diagnostic_cases(id) ON DELETE RESTRICT, conclusion text NOT NULL, certainty text NOT NULL CHECK(certainty IN ('CONFIRMED','PROBABLE','UNDETERMINED')), supporting_evidence jsonb NOT NULL DEFAULT '[]'::jsonb, contradicting_evidence jsonb NOT NULL DEFAULT '[]'::jsonb, recorded_by uuid REFERENCES sys_users(id) ON DELETE RESTRICT, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE estimate_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES diagnostic_cases(id) ON DELETE RESTRICT, revision_no integer NOT NULL CHECK(revision_no>0), status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','ISSUED','ACCEPTED','REJECTED','EXPIRED','SUPERSEDED')), currency char(3) NOT NULL DEFAULT 'CAD', total_amount numeric(12,2) NOT NULL DEFAULT 0 CHECK(total_amount>=0), terms_snapshot text NOT NULL DEFAULT '', content_sha256 char(64), issued_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(case_id,revision_no));
CREATE TABLE estimate_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), estimate_revision_id uuid NOT NULL REFERENCES estimate_revisions(id) ON DELETE RESTRICT, item_type text NOT NULL CHECK(item_type IN ('DIAGNOSTIC','LABOUR','PART','TRAVEL','DISPOSAL','DISCOUNT','TAX','OTHER')), description text NOT NULL, quantity numeric(12,3) NOT NULL DEFAULT 1 CHECK(quantity>0), unit_price numeric(12,2) NOT NULL, line_total numeric(12,2) NOT NULL);
CREATE TABLE authorizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES diagnostic_cases(id) ON DELETE RESTRICT, estimate_revision_id uuid REFERENCES estimate_revisions(id) ON DELETE RESTRICT, authorization_stage text NOT NULL CHECK(authorization_stage IN ('DIAGNOSTIC_FEE','REPAIR_APPROVAL','COMPLETION_ACK')), decision text NOT NULL CHECK(decision IN ('APPROVED','DECLINED','PENDING_REVIEW')), consent_method text NOT NULL CHECK(consent_method IN ('SIGNATURE','VERBAL','EMAIL','TEXT','REFUSED_TO_SIGN','OTHER')), scope_snapshot text NOT NULL, scope_sha256 char(64), customer_name_snapshot text, signed_media_id uuid REFERENCES diagnostic_media(id) ON DELETE RESTRICT, collected_offline boolean NOT NULL DEFAULT false, reviewed_at timestamptz, recorded_at timestamptz NOT NULL DEFAULT now(), CHECK(authorization_stage<>'REPAIR_APPROVAL' OR estimate_revision_id IS NOT NULL));
CREATE INDEX ix_auth_case ON authorizations(case_id,recorded_at DESC);
CREATE TABLE repair_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES diagnostic_cases(id) ON DELETE RESTRICT, visit_id uuid REFERENCES service_visits(id) ON DELETE RESTRICT, authorization_id uuid REFERENCES authorizations(id) ON DELETE RESTRICT, action_type text NOT NULL CHECK(action_type IN ('CLEAN','ADJUST','REPAIR','REPLACE','REASSEMBLE','OTHER')), component text, description text NOT NULL, action_status text NOT NULL DEFAULT 'PLANNED' CHECK(action_status IN ('PLANNED','IN_PROGRESS','COMPLETED','FAILED','ABORTED')), failure_reason text, performed_by uuid REFERENCES sys_users(id) ON DELETE RESTRICT, started_at timestamptz, completed_at timestamptz);
CREATE INDEX ix_actions_case ON repair_actions(case_id);
CREATE TABLE installed_parts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), repair_action_id uuid NOT NULL REFERENCES repair_actions(id) ON DELETE RESTRICT, part_name text NOT NULL, part_number text, part_source text, serial_or_lot text, quantity numeric(12,3) NOT NULL DEFAULT 1 CHECK(quantity>0), unit_cost numeric(12,2), condition text CHECK(condition IN ('NEW','REFURBISHED','USED','UNKNOWN')), installation_result text CHECK(installation_result IN ('INSTALLED','DOA','DAMAGED','REMOVED','RETURNED')), notes text);
CREATE TABLE verification_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_name text NOT NULL, appliance_type text NOT NULL, version_no integer NOT NULL DEFAULT 1 CHECK(version_no>0), active boolean NOT NULL DEFAULT true, UNIQUE(template_name,version_no));
CREATE TABLE repair_verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES diagnostic_cases(id) ON DELETE RESTRICT, visit_id uuid REFERENCES service_visits(id) ON DELETE RESTRICT, template_id uuid REFERENCES verification_templates(id) ON DELETE RESTRICT, verification_round integer NOT NULL DEFAULT 1 CHECK(verification_round>0), overall_result text NOT NULL CHECK(overall_result IN ('PENDING','PASS','FAIL','NA','NOT_COMPLETED')), notes text, performed_by uuid REFERENCES sys_users(id) ON DELETE RESTRICT, performed_at timestamptz, UNIQUE(case_id,verification_round));
CREATE TABLE verification_checks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), verification_id uuid NOT NULL REFERENCES repair_verifications(id) ON DELETE RESTRICT, check_name text NOT NULL, expected_result text, actual_result text, result text NOT NULL CHECK(result IN ('PASS','FAIL','NA','NOT_COMPLETED')), reason text, CHECK(result NOT IN ('NA','NOT_COMPLETED') OR reason IS NOT NULL));
CREATE TABLE payment_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES diagnostic_cases(id) ON DELETE RESTRICT, amount numeric(12,2) NOT NULL CHECK(amount>=0), currency char(3) NOT NULL DEFAULT 'CAD', payment_method text NOT NULL, payment_status text NOT NULL CHECK(payment_status IN ('PENDING','RECEIVED','REFUNDED','VOID')), reference_no text, received_at timestamptz);
CREATE TABLE warranties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES diagnostic_cases(id) ON DELETE RESTRICT, repair_action_id uuid REFERENCES repair_actions(id) ON DELETE RESTRICT, warranty_type text NOT NULL CHECK(warranty_type IN ('LABOUR','PART','SERVICE')), coverage_snapshot text NOT NULL, starts_on date NOT NULL, ends_on date, CHECK(ends_on IS NULL OR ends_on>=starts_on));
CREATE TABLE knowledge_candidates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_case_id uuid REFERENCES diagnostic_cases(id) ON DELETE RESTRICT, rule_key text NOT NULL, version_no integer NOT NULL CHECK(version_no>0), title text NOT NULL, hypothesis_text text NOT NULL, review_status text NOT NULL DEFAULT 'CANDIDATE' CHECK(review_status IN ('CANDIDATE','IN_REVIEW','APPROVED','REJECTED','SUPERSEDED')), reviewed_by uuid REFERENCES sys_users(id) ON DELETE RESTRICT, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(rule_key,version_no));
CREATE TABLE knowledge_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES knowledge_candidates(id) ON DELETE RESTRICT, case_id uuid NOT NULL REFERENCES diagnostic_cases(id) ON DELETE RESTRICT, evidence_relation text NOT NULL CHECK(evidence_relation IN ('SUPPORTS','CONTRADICTS')), evidence_note text, UNIQUE(candidate_id,case_id,evidence_relation));
CREATE TABLE sync_mutations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid NOT NULL REFERENCES sys_users(id) ON DELETE RESTRICT, client_mutation_id uuid NOT NULL, device_id text NOT NULL, entity_type text NOT NULL, entity_id uuid NOT NULL, operation text NOT NULL, status text NOT NULL CHECK(status IN ('ACCEPTED','REJECTED')), response_payload jsonb NOT NULL DEFAULT '{}'::jsonb, processed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(actor_user_id,client_mutation_id));
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid REFERENCES sys_users(id) ON DELETE RESTRICT, event_type text NOT NULL, entity_type text NOT NULL, entity_id uuid, correlation_id text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ix_audit_entity ON audit_events(entity_type,entity_id,occurred_at DESC);
COMMIT;
